if [ "\$1" = "push" ]; then
  raced_tag=""
  for a in "\$@"; do
    case "\$a" in
      refs/tags/v*) raced_tag="\${a#refs/tags/}" ;;
    esac
  done
  if [ -n "\$raced_tag" ] && [ -f "\$FA_RACE_FILE" ]; then
    race_left=\$(cat "\$FA_RACE_FILE")
