      echo \$((race_left-1)) > "\$FA_RACE_FILE"
      "\$FA_REAL_GIT" -C "\$FA_RACER" tag -a "\$raced_tag" -m "Release \$raced_tag" origin/main
      "\$FA_REAL_GIT" -C "\$FA_RACER" push -q origin "refs/tags/\$raced_tag"
    fi
  fi
fi
''';
