        reason: 'fixture: the python section-prepend must be locatable',
      );
      expect(
        guard,
        greaterThan(prepend),
        reason:
            'the guard must measure the POST-section staged changelog — '
            'the stage just grew by the fresh tag section (gh-1522)',
      );
    },
  );

