    final dir = _fixture('missing');
    expect(_run(const [], dir), 1);
  });

  test('repo CHANGELOG.md is under the cap (the gh-1452 trim landed)', () {
    final f = File('CHANGELOG.md');
    expect(f.existsSync(), isTrue);
    expect(
      f.lengthSync(),
      lessThan(262144),
      reason:
