    this.body = body;
  }

  final String line;
  final bool negated;
  final bool dirOnly;
  late final bool anchored;
  late final String body;

  bool matches(String path, bool isDir) {
    if (dirOnly && !isDir) return false;
    return _globMatch(body, path);
