      greaterThan(publish),
      reason:
          'the publish job must fast-fail before dart pub publish — '
          'the server reject (v1.0.538) is the worst possible discovery '
          'point',
    );
    final stage = ci.indexOf(
      'stage_publish_package.sh /tmp/publish-stage',
